import { validateRavAssistantSourceIds } from './rav-assistant-sources-v1.js';

// Geology, material science, identification and conservation.
// Answers are intentionally concise; sourceIds carry the deeper provenance.
export const RAV_ASSISTANT_RESEARCH_MATERIAL = Object.freeze([
  fact('amber-refractive-index', /^(?:hvad er (?:ravets (?:typiske )?brydningsindeks|(?:det typiske )?brydningsindeks (?:for|i) rav)|hvad betyder brydningsindeks for rav|welchen (?:typischen )?brechungsindex hat bernstein|was ist (?:der (?:typische )?)?brechungsindex (?:von|bei) bernstein|what is (?:the (?:typical )?)?refractive index of amber)[.!?\s]*$/iu,
    'official-guidance', ['gia-amber'],
    'GIA angiver et typisk brydningsindeks på cirka 1,540 for rav. Det er en optisk materialeegenskab, ikke massefylde eller alder. Tallet er en reference, ikke en måling af dit fund og ikke alene bevis for ægthed.',
    'GIA nennt für Bernstein einen typischen Brechungsindex von ungefähr 1,540. Er beschreibt eine optische Materialeigenschaft, nicht Dichte oder Alter. Der Wert ist eine Referenz, keine Messung deines Fundes und allein kein Echtheitsbeweis.',
    'GIA lists a typical refractive index of about 1.540 for amber. This is an optical material property, not density or age. It is a reference, not a measurement of your find or sufficient proof of authenticity.',
    ['Hvad er ravets typiske brydningsindeks?','Welchen typischen Brechungsindex hat Bernstein?','What is the typical refractive index of amber?']),
  fact('amber-chemical-formula-limit', /^(?:er c10h16o (?:den præcise )?kemiske formel for (?:alt )?rav|hvad er (?:ravets kemiske formel|den kemiske formel for rav)|ist c10h16o die (?:genaue )?chemische formel für (?:jeden )?bernstein|was ist die chemische formel (?:von|für) bernstein|is c10h16o the (?:exact )?chemical formula for (?:all )?amber|what is (?:the chemical formula (?:of|for) amber|amber.?s chemical formula))[.!?\s]*$/iu,
    'mixed', ['gia-amber','amber-spectroscopy-2025'],
    'C10H16O bruges som en forenklet oversigtsformel for rav. Naturligt rav er ikke ét rent stof med én præcis, universel molekylformel: det rummer en kemisk blanding og et modnet netværk, hvis sammensætning varierer. Formlen identificerer derfor ikke dit fund.',
    'C10H16O wird als vereinfachte Übersichtsformel für Bernstein verwendet. Natürlicher Bernstein ist kein einzelner Reinstoff mit einer exakten, universellen Molekülformel: Er enthält ein chemisches Gemisch und ein gereiftes Netzwerk mit variabler Zusammensetzung. Die Formel identifiziert daher keinen Fund.',
    'C10H16O is used as a simplified overview formula for amber. Natural amber is not one pure substance with a single exact universal molecular formula: it contains a chemical mixture and a matured network with varying composition. The formula does not identify your find.',
    ['Er C10H16O den præcise kemiske formel for alt rav?','Ist C10H16O die genaue chemische Formel für jeden Bernstein?','Is C10H16O the exact chemical formula for all amber?']),
  fact('amber-root-variety', /^(?:hvad (?:er|betyder) (?:root amber|rodrav)|was (?:ist|bedeutet) (?:wurzelbernstein|root amber)|what (?:is|does) root amber(?: mean)?)[.!?\s]*$/iu,
    'direct-analysis', ['gia-root-amber'],
    'Root amber er en ravvariant fra Myanmar med farver og struktur, der kan minde om rødder. Navnet betyder ikke en fossil rod. GIA har undersøgt både naturligt materiale, rekonstrueret rav og plastimitationer med dette udseende; navnet alene beviser ikke ægthed.',
    'Root amber oder Wurzelbernstein bezeichnet eine Bernsteinvarietät aus Myanmar mit wurzelähnlicher Farbe und Struktur, keine fossile Wurzel. GIA untersuchte natürliche Stücke, rekonstruierten Bernstein und Kunststoffimitationen dieses Aussehens. Der Name allein beweist keine Echtheit.',
    'Root amber is an amber variety from Myanmar with root-like colour and structure, not a fossil root. GIA examined natural material, reconstructed amber and plastic imitations with this appearance. The name alone does not prove authenticity.',
    ['Hvad betyder root amber?','Was bedeutet Wurzelbernstein?','What does root amber mean?']),
  fact('amber-cabochon', /^(?:hvad er en (?:cabochon af rav|ravcabochon)|was ist ein (?:cabochon aus bernstein|bernstein.?cabochon)|what is an amber cabochon)[.!?\s]*$/iu,
    'official-guidance', ['gia-gem-cut-terms','gia-amber-quality'],
    'En ravcabochon er glatslebet uden facetter. En enkel cabochon har hvælvet overside og flad bund; en dobbelt cabochon er afrundet på begge sider. Det beskriver slibningen, ikke ravets kemiske type, ægthed eller kvalitet.',
    'Ein Bernstein-Cabochon ist glatt und ohne Facetten geschliffen. Ein einfacher Cabochon hat eine gewölbte Oberseite und flache Unterseite; ein doppelter ist beidseitig gerundet. Das beschreibt den Schliff, nicht chemischen Typ, Echtheit oder Qualität des Bernsteins.',
    'An amber cabochon is smoothly cut without facets. A simple cabochon has a domed top and flat base; a double cabochon is rounded on both sides. This describes the cut, not the amber’s chemical type, authenticity or quality.',
    ['Hvad er en cabochon af rav?','Was ist ein Cabochon aus Bernstein?','What is an amber cabochon?']),
  fact('amber-faceting', /^(?:kan (?:ægte )?rav være facetslebet|kan (?:ægte )?rav (?:facetslibes|have facetter)|kann (?:echter )?bernstein facettiert (?:sein|werden)|can (?:genuine )?amber (?:be faceted|have facets))[.!?\s]*$/iu,
    'official-guidance', ['gia-amber-quality'],
    'Ja, rav kan facetslibes, selv om det er usædvanligt. GIA beskriver frie polerede former, perler og cabochoner som almindelige slibninger. Facetter gør derfor ikke i sig selv et stykke falsk, men beviser heller ikke ægthed.',
    'Ja, Bernstein kann facettiert sein, obwohl dies ungewöhnlich ist. GIA nennt freie polierte Formen, Perlen und Cabochons als übliche Schliffe. Facetten beweisen deshalb weder eine Fälschung noch Echtheit.',
    'Yes, amber can be faceted, although this is uncommon. GIA describes freeform polished pieces, beads and cabochons as usual cutting styles. Facets therefore do not by themselves make a piece fake or prove authenticity.',
    ['Kan ægte rav være facetslebet?','Kann echter Bernstein facettiert sein?','Can genuine amber be faceted?']),
  fact('amber-metric-carat', /^(?:hvad betyder karat (?:når man vejer rav|for ravs vægt)|hvor meget vejer (?:en|1) karat rav|was bedeutet karat beim wiegen von bernstein|wie viel wiegt (?:ein|1) karat bernstein|what does carat mean when weighing amber|how much does (?:one|1) carat of amber weigh)[.!?\s]*$/iu,
    'official-guidance', ['gia-metric-carat'],
    'Karat er her en masseenhed: 1 ct = 0,2 gram = 200 milligram, så 1 gram er 5 ct. Det fortæller ikke stykkets mål, renhed eller ægthed. Karat som masse for smykkesten må ikke forveksles med karat som renhedsangivelse for guld.',
    'Karat ist hier eine Masseneinheit: 1 ct = 0,2 Gramm = 200 Milligramm; 1 Gramm entspricht 5 ct. Das sagt nichts über Abmessungen, Reinheit oder Echtheit aus. Edelstein-Karat als Masse ist nicht Gold-Karat als Reinheitsangabe.',
    'Carat is a mass unit here: 1 ct = 0.2 grams = 200 milligrams, so 1 gram equals 5 ct. It does not state dimensions, purity or authenticity. Gemstone carat mass must not be confused with gold karat purity.',
    ['Hvad betyder karat når man vejer rav?','Was bedeutet Karat beim Wiegen von Bernstein?','What does carat mean when weighing amber?']),
  fact('amber-ultrasonic-cleaning', /(?=.*\b(?:rav(?:et|ets)?|bernsteins?|amber)\b)(?=.*(?:ultralyd|ultraschall|ultrasonic))/iu,
    'official-guidance', ['gia-ultrasonic-care','gia-amber-cleaning'],
    'Undgå ultralydsrensning af rav. GIA fraråder det udtrykkeligt for organiske smykkematerialer. Brug i stedet skånsom rengøring med lunkent vand og mild sæbe. Værdifulde eller skrøbelige fund bør vurderes før rengøring.',
    'Bernstein nicht im Ultraschall reinigen: GIA schließt organische Schmuckmaterialien ausdrücklich aus. Stattdessen vorsichtig mit lauwarmem Wasser und milder Seife reinigen. Wertvolle oder empfindliche Funde vorher fachlich beurteilen lassen.',
    'Avoid ultrasonic cleaning of amber: GIA explicitly excludes organic gem materials. Use gentle lukewarm water and mild soap instead. Seek advice before cleaning valuable or fragile finds.',
    ['Må rav renses i ultralyd?','Darf Bernstein im Ultraschall gereinigt werden?','Can amber be cleaned ultrasonically?']),
  fact('amber-steam-cleaning', /(?=.*\b(?:rav(?:et|ets)?|bernsteins?|amber)\b)(?=.*(?:damprens|damp.*rens|dampf.*reinig|steam[ -]?clean))/iu,
    'official-guidance', ['gia-amber-cleaning'],
    'Damprens ikke rav. Materialet er varmefølsomt; en maskine til hårdere ædelsten er ikke automatisk egnet. GIA anbefaler mild sæbe og varmt, ikke kogende, vand.',
    'Bernstein nicht dampfreinigen. Er ist hitzeempfindlich; Geräte für härtere Edelsteine sind nicht automatisch geeignet. GIA empfiehlt milde Seife und warmes, nicht kochendes Wasser.',
    'Do not steam-clean amber. It is heat-sensitive; equipment for harder gems is not automatically suitable. GIA recommends mild soap and warm, not boiling, water.',
    ['Må jeg damprense rav?','Darf ich Bernstein mit Dampf reinigen?','Can I steam-clean amber?']),
  fact('amber-hardness-toughness', /(?=.*\b(?:rav(?:et|ets)?|bernsteins?|amber)\b)(?=.*(?:hårdhed|härte|hardness))(?=.*(?:sejhed|zähigkeit|toughness))/iu,
    'official-guidance', ['gia-amber-cleaning'],
    'Hårdhed beskriver modstand mod ridser, sejhed mod brud. Rav har lav hårdhed og ringe sejhed. At det føles hårdt, betyder ikke at det tåler slag.',
    'Härte beschreibt Kratzfestigkeit, Zähigkeit Bruchfestigkeit. Bernstein besitzt geringe Härte und geringe Zähigkeit. Ein hartes Gefühl bedeutet nicht, dass er Stöße verträgt.',
    'Hardness describes resistance to scratching; toughness concerns breaking. Amber has low hardness and poor toughness. Feeling hard does not mean it tolerates impacts.',
    ['Er hårdhed og sejhed det samme for rav?','Sind Härte und Zähigkeit bei Bernstein dasselbe?','Are hardness and toughness the same for amber?']),
  fact('amber-darkening-authenticity', /(?=.*\b(?:rav(?:et|ets)?|bernsteins?|amber)\b)(?=.*(?:blevet mørkere|mørkner|dunkler geworden|dunkelt|become darker|darkened|darkening))(?=.*(?:falsk|ægte|unecht|echt|fake|genuine|real))/iu,
    'official-guidance', ['gia-amber-darkening'],
    'Poleret rav kan oxidere og blive mørkere på overfladen med alderen. Farveskift beviser derfor ikke at det er falsk. Opvarmning kan også give mørkning; farven alene beviser heller ikke ubehandlet ægthed.',
    'Polierter Bernstein kann mit der Zeit außen oxidieren und dunkler werden. Das beweist keine Fälschung. Erhitzen kann ebenfalls verdunkeln; Farbe allein beweist deshalb auch keine unbehandelte Echtheit.',
    'Polished amber can oxidise and darken at the surface as it ages. That does not prove it is fake. Heating can also darken it; colour alone cannot establish untreated authenticity.',
    ['Er rav der er blevet mørkere falsk?','Ist dunkler gewordener Bernstein unecht?','Is amber that has become darker fake?']),
  fact('amber-sun-spangles', /(?=.*\b(?:rav(?:et|ets)?|bernsteins?|amber)\b)(?=.*(?:solskiver|sonnenscheibchen|sonnenflinten|sun[ -]?(?:spangles|sparks)))/iu,
    'direct-experiment', ['gia-heat-treatment'],
    'Solskiver eller sun spangles kan være skiveformede indre revner frembragt ved varme- og trykbehandling. De er ikke automatisk fossile blomster. Sådanne mønstre kræver faglig vurdering, ikke en ægthedsdom ud fra et foto.',
    'Sonnenscheibchen, auch sun spangles, können scheibenförmige innere Risse aus Wärme- und Druckbehandlung sein, nicht fossile Blumen. Das Muster braucht fachliche Beurteilung, kein Echtheitsurteil allein anhand eines Fotos.',
    'Sun spangles can be disc-shaped internal cracks produced by heat and pressure treatment, not fossil flowers. Such patterns need expert assessment, not an authenticity verdict from a photo alone.',
    ['Hvad er solskiver i rav?','Was sind Sonnenscheibchen im Bernstein?','What are sun spangles in amber?']),
  fact('amber-pressure-clarification', /(?=.*\b(?:rav(?:et|ets)?|bernsteins?|amber)\b)(?=.*(?:trykbehandling|druckbehandlung|pressure treatment))(?=.*(?:gennemsigtig|klarere|durchsichtig|transparen|clearer))/iu,
    'direct-experiment', ['gia-heat-treatment'],
    'Kontrolleret varme- og trykbehandling kan reducere uklarhed fra bobler og gøre rav mere gennemsigtigt. Det er ændring af materialet, ikke bevis for naturlig klarhed. Det er ingen anbefaling om at opvarme dine fund hjemme.',
    'Kontrollierte Wärme- und Druckbehandlung kann Blasentrübung verringern und Bernstein transparenter machen. Das verändert das Material und beweist keine natürliche Klarheit. Es ist keine Empfehlung, eigene Funde zu Hause zu erhitzen.',
    'Controlled heat and pressure treatment can reduce bubble cloudiness and increase transparency. This alters the material; it does not prove natural clarity. It is not advice to heat your finds at home.',
    ['Kan trykbehandling gøre rav gennemsigtigt?','Kann Druckbehandlung Bernstein transparenter machen?','Can pressure treatment make amber transparent?']),
  fact('amber-insect-soft-tissue', /(?=.*\b(?:rav(?:et|ets)?|bernsteins?|amber)\b)(?=.*(?:insekt|insect))(?=.*(?:blødt væv|weichgewebe|soft tissue))/iu,
    'expert-scientific-explanation', ['nhm-amber-dna'],
    'Et tydeligt insekt i rav betyder ikke at alle bløde væv eller blod er bevaret. Ydre form og indre biologisk indhold er forskellige ting. Et flot foto dokumenterer ikke levende celler eller brugbart arvemateriale.',
    'Ein gut sichtbares Insekt im Bernstein bedeutet nicht, dass Weichgewebe oder Blut vollständig erhalten sind. Äußere Form und innerer biologischer Inhalt sind verschieden. Ein Foto belegt keine lebenden Zellen oder nutzbare Erbinformation.',
    'A clearly visible insect in amber does not mean all soft tissue or blood survived. External shape and internal biological content differ. A striking photograph does not establish living cells or usable genetic material.',
    ['Er alt blødt væv bevaret i et insekt i rav?','Ist alles Weichgewebe eines Insekts im Bernstein erhalten?','Is all soft tissue preserved in an insect in amber?']),
  fact('amber-dna-limit', /(?=.*\b(?:rav(?:et|ets)?|bernsteins?|amber)\b)(?=.*(?:dinosaur\p{L}*[ -]?dna|jurassic park))/iu,
    'expert-scientific-explanation', ['nhm-amber-dna'],
    'Jurassic Park er ikke dokumentation for at genskabe dinosaurer fra rav. En bevaret insektform viser ikke at brugbart dinosaur-DNA findes indeni. Selv mulige blodrester er ikke det samme som et bevaret genom.',
    'Jurassic Park belegt keine Wiedererschaffung von Dinosauriern aus Bernstein. Eine erhaltene Insektenform zeigt keine nutzbare Dinosaurier-DNA im Inneren. Selbst mögliche Blutreste sind nicht dasselbe wie ein erhaltenes Genom.',
    'Jurassic Park does not establish dinosaur resurrection from amber. A preserved insect shape does not show usable dinosaur DNA inside. Even possible blood residues are not the same as a preserved genome.',
    ['Kan et insekt i rav levere dinosaur-DNA?','Kann ein Insekt im Bernstein Dinosaurier-DNA liefern?','Can an insect in amber supply dinosaur DNA?']),
  fact('amber-anisotropy-evidence', /(?=.*\b(?:rav(?:et|ets)?|bernsteins?|amber)\b)(?=.*anisotrop)/iu,
    'direct-amber', ['gia-amorphous-materials','rr-systematic-review'],
    'Anisotropi betyder, at en målt egenskab afhænger af retningen. Rav er amorft, ikke opbygget af et regelmæssigt krystalgitter. Derfor skal vi ikke forklare dets bevægelse med påståede krystalakser eller krystallag. Det beviser heller ikke, at alle egenskaber i ethvert stykke er ens i alle retninger: form, indeslutninger og prøvens tilstand skal holdes adskilt fra molekylestruktur. RavRadars kildegrundlag giver ikke en universel anisotropikonstant eller en dokumenteret transportretning ud fra anisotropi. En sådan påstand kræver en konkret prøve, en angivet egenskab og retningsafhængige målinger.',
    'Anisotropie bedeutet, dass eine gemessene Eigenschaft von der Richtung abhängt. Bernstein ist amorph und besitzt kein regelmäßiges Kristallgitter. Seine Bewegung darf daher nicht mit behaupteten Kristallachsen oder Kristallschichten erklärt werden. Das beweist auch nicht, dass jede Eigenschaft jedes Stücks in allen Richtungen gleich ist: Form, Einschlüsse und Zustand der Probe sind von der Molekülstruktur zu trennen. RavRadars Quellen liefern keine universelle Anisotropiekonstante oder daraus belegte Transportrichtung. Dafür braucht es eine konkrete Probe, eine benannte Eigenschaft und richtungsabhängige Messungen.',
    'Anisotropy means a measured property depends on direction. Amber is amorphous, not a regular crystal lattice, so its movement must not be explained by invented crystal axes or crystal layers. This does not prove every property of every piece is identical in all directions: shape, inclusions and sample condition must be separated from molecular structure. RavRadar’s sources supply no universal anisotropy constant or proven transport direction derived from anisotropy. Such a claim needs a specific sample, a named property and direction-dependent measurements.',
    ['Hvad er dokumenteret om anisotropi i rav?','Was ist über Anisotropie in Bernstein belegt?','What is documented about anisotropy in amber?']),
  fact('amber-optical-molecular-evidence', /(?=.*\b(?:rav(?:et|ets)?|bernsteins?|amber)\b)(?=.*(?:optisk|optisch|optical))(?=.*(?:molekyl|molekul|molecular|binding|bindunge?n?|bonds?|kemisk|chemisch|chemical))/iu,
    'direct-amber', ['amber-spectroscopy-2025','gia-amorphous-materials'],
    'Ravets optiske egenskaber hænger sammen med dets kemiske blanding og struktur. Spektroskopiske undersøgelser viser variation i absorption og fluorescens mellem prøver og efter varmebehandling. Det er måleviden; det identificerer ikke automatisk én bestemt binding som forklaring på alle ravstykkers farve eller lys. Rav er amorft, ikke et krystalgitter, og kan være klart, mælket eller uklart. En præcis sammenhæng mellem en molekylær binding og en optisk effekt kræver prøvespecifik analyse. Optiske målinger alene viser ikke, hvordan stykket transporteres på stranden.',
    'Die optischen Eigenschaften von Bernstein hängen mit seiner chemischen Mischung und Struktur zusammen. Spektroskopische Untersuchungen zeigen Unterschiede in Absorption und Fluoreszenz zwischen Proben und nach Wärmebehandlung. Das ist Messwissen, identifiziert aber nicht automatisch eine einzelne Bindung als Erklärung jeder Farbe oder Lichtwirkung. Bernstein ist amorph, kein Kristallgitter, und kann klar, milchig oder undurchsichtig sein. Eine genaue Verbindung zwischen molekularer Bindung und optischer Wirkung braucht eine probenspezifische Analyse. Optische Messungen allein erklären keinen Strandtransport.',
    'Amber’s optical properties relate to its chemical mixture and structure. Spectroscopic studies show absorption and fluorescence vary between samples and after heating. Those are measurements, not automatic identification of one bond explaining every piece’s colour or glow. Amber is amorphous, not a crystal lattice, and may be clear, milky or opaque. A precise link between a molecular bond and an optical effect needs sample-specific analysis. Optical measurements alone do not show how a piece moves along the beach.',
    ['Hvordan hænger ravets molekylære bindinger sammen med optiske egenskaber?','Wie hängen molekulare Bindungen in Bernstein mit optischen Eigenschaften zusammen?','How do molecular bonds in amber relate to optical properties?']),
  fact('amber-chemistry-variation', /(?=.*(?:rav|bernstein|amber))(?=.*(?:kemi|kemisk.*sammensæt|chemistry|chemical composition|chemie|chemische.*zusammensetzung))(?=.*(?:vari|forskel|forskellig|different|differ|unterschied))/iu,
    'direct-amber', ['seyfullah-resin-2018','wolfe-origin-2009'],
    'Ja, ravtyper kan have forskellig kemi, blandt andet fordi de oprindelige planter havde forskellig harpiks. Kemisk modning og varmehistorik spiller også ind. Men forskellen kan ikke tilskrives geologisk periode alene: beslægtet harpiks kan bevare kemiske ligheder over lang tid. Et løst strandfund kan derfor ikke dateres præcist ud fra farven eller et almindeligt hjemmetjek; oprindelse og datering kræver faglig analyse og geologisk kontekst.',
    'Ja, Bernsteintypen können sich chemisch unterscheiden, unter anderem durch verschiedene ursprüngliche Pflanzenharze. Reifung und Wärmegeschichte spielen ebenfalls mit. Die geologische Periode allein erklärt den Unterschied jedoch nicht: verwandte Harze können lange chemisch ähnlich bleiben. Ein loser Strandfund lässt sich deshalb nicht genau anhand der Farbe oder eines Heimtests datieren; Herkunft und Alter brauchen Fachanalyse und geologischen Kontext.',
    'Yes, amber types can differ chemically, partly because their source plants produced different resins. Maturation and thermal history also matter. But geological period alone does not explain the difference: related resins can retain chemical similarities over long spans. A loose beach find cannot therefore be dated precisely by colour or a home test; origin and dating require specialist analysis and geological context.',
    ['Kan ravets kemiske sammensætning variere mellem geologiske perioder?','Kann die chemische Zusammensetzung von Bernstein zwischen geologischen Perioden variieren?','Can the chemical composition of amber differ between geological periods?']),
  fact('resin-vs-sap', /(?:forskel|forskellen).*(?:harpiks|saft)|harpiks.*(?:saft|træsaft)|unterschied.*(?:harz|baumsaft)|harz.*baumsaft|difference.*(?:resin|sap)|resin.*tree sap/iu,
    'direct-amber', ['seyfullah-resin-2018'],
    'Harpiks er ikke det samme som almindelig træsaft. Harpiks er en kemisk særskilt planteudskillelse, ofte rig på terpenstoffer, som kan hærde og under særlige forhold modnes til rav.',
    'Harz ist nicht dasselbe wie gewöhnlicher Baumsaft. Es ist ein chemisch eigenes Pflanzensekret, oft reich an Terpenen, das aushärten und unter besonderen Bedingungen zu Bernstein reifen kann.',
    'Resin is not the same as ordinary tree sap. It is a chemically distinct plant secretion, often rich in terpenes, that can harden and, under special conditions, mature into amber.',
    ['Hvad er forskellen på harpiks og træsaft?','Was ist der Unterschied zwischen Harz und Baumsaft?','What is the difference between resin and tree sap?']),
  fact('resin-fossilisation', /hvordan.*(?:harpiks|resin).*bliver.*rav|rav.*(?:dannes|fossiliser)|wie.*harz.*bernstein|bernstein.*(?:entsteh|fossilis)|how.*resin.*(?:become|turn into).*amber|amber.*fossili[sz]/iu,
    'direct-amber', ['seyfullah-resin-2018'],
    'Harpiks bliver ikke rav ved blot at tørre. Den skal hærde, begraves og gennemgå langsom kemisk modning med tab af flygtige stoffer, polymerisering og krydsbinding over geologisk tid.',
    'Harz wird nicht allein durch Trocknen zu Bernstein. Es muss aushärten, begraben werden und über geologische Zeit langsam flüchtige Stoffe verlieren, polymerisieren und sich vernetzen.',
    'Resin does not become amber simply by drying. It must harden, be buried and undergo slow chemical maturation, including loss of volatiles, polymerisation and cross-linking over geological time.',
    ['Hvordan bliver harpiks fossiliseret til rav?','Wie wird Harz zu Bernstein fossilisiert?','How does resin fossilise into amber?']),
  fact('amber-molecular-network', /(?=.*\b(?:rav(?:et|ets)?|bernsteins?|amber)\b)(?=.*(?:polymer|krydsbinding|cross.?link|vernetz|amorf|amorph))|er rav(?:et)? (?:en )?krystal|ist bernstein (?:ein )?kristall|is amber (?:a )?crystal/iu,
    'direct-amber', ['seyfullah-resin-2018','gia-amorphous-materials'],
    'Polymerisering binder mindre molekyler sammen til større molekyler eller kæder. Krydsbinding forbinder kæderne og kan danne et mere stabilt netværk under harpiksens modning. Rav er amorft: det har ikke en krystals regelmæssige indre gitter. At rav bliver fast betyder altså ikke, at det krystalliserer. Kemiske netværk varierer mellem ravtyper; dette forklarer modning, men daterer ikke et bestemt strandfund.',
    'Polymerisation verbindet kleinere Moleküle zu größeren Molekülen oder Ketten. Vernetzung verbindet die Ketten und kann während der Harzreifung ein stabileres Netzwerk bilden. Bernstein ist amorph: Er hat kein regelmäßiges inneres Kristallgitter. Festwerden bedeutet daher nicht Kristallisation. Die chemischen Netzwerke unterscheiden sich zwischen Bernsteintypen; dies erklärt Reifung, datiert aber keinen bestimmten Strandfund.',
    'Polymerisation joins smaller molecules into larger molecules or chains. Cross-linking connects chains and can form a more stable network as resin matures. Amber is amorphous: it lacks a crystal’s regular internal lattice. Becoming solid therefore does not mean crystallising. Chemical networks vary among amber types; this explains maturation but does not date a particular beach find.',
    ['Hvad betyder polymerisering og krydsbinding under ravets modning?','Was bedeuten Polymerisation und Vernetzung bei der Reifung von Bernstein?','What do polymerisation and cross-linking mean as amber matures?']),
  fact('amber-organic-gem', /(?:rav|bernstein|amber).*(?:organisk|organic|organisch).*(?:ædelsten|smykkesten|gem)|(?:ædelsten|smykkesten).*(?:rav)|organischer schmuckstein|organic gem/iu,
    'official-guidance', ['gia-amber','seyfullah-resin-2018'],
    'Rav regnes som en organisk smykkesten, fordi det stammer fra planteharpiks og ikke fra en mineralsk krystal. Det ændrer ikke, at naturligt rav kan være meget gammelt og geologisk værdifuldt.',
    'Bernstein gilt als organischer Schmuckstein, weil er aus Pflanzenharz und nicht aus einem Mineralkristall entstand. Natürlicher Bernstein kann dennoch sehr alt und geologisch wertvoll sein.',
    'Amber is classed as an organic gem because it comes from plant resin rather than a mineral crystal. Natural amber can still be extremely old and geologically valuable.',
    ['Er rav en organisk smykkesten?','Ist Bernstein ein organischer Schmuckstein?','Is amber an organic gem?']),
  fact('baltic-succinite', /hvad.*succinit|succinit.*rav|was.*succinit|succinit.*bernstein|what.*succinite|succinite.*amber/iu,
    'direct-amber', ['ross-age-2026','seyfullah-resin-2018'],
    'Succinit er navnet på den dominerende kemiske type baltisk rav. Udtrykket baltisk rav bruges nogle gange bredere, så en løs etiket fortæller ikke alene et stykkes præcise oprindelse.',
    'Succinit ist die Bezeichnung für den vorherrschenden chemischen Typ des baltischen Bernsteins. Der Ausdruck baltischer Bernstein wird teils weiter benutzt und beweist allein keine genaue Herkunft.',
    'Succinite is the name of the dominant chemical type of Baltic amber. The term Baltic amber is sometimes used more broadly, so a label alone does not prove a piece’s exact origin.',
    ['Hvad er succinit?','Was ist Succinit?','What is succinite?']),
  fact('baltic-age-range', /(?:baltisk|baltic|baltischer).*(?:rav|amber|bernstein).*(?:alder|gammel|age|old|alter)|(?:alder|age|alter).*(?:baltisk rav|baltic amber|baltischer bernstein)/iu,
    'direct-amber', ['ross-age-2026','geus-fanoe'],
    'Den nyeste stratigrafiske gennemgang placerer det vigtigste baltiske succinitlag i sen Eocæn, cirka 36–35 millioner år før nu. Baltisk rav uden sikker lagproveniens angives bredere til omtrent 37,7–34 millioner år.',
    'Die neueste stratigraphische Übersicht datiert die wichtigste baltische Succinit-Schicht in das späte Eozän, etwa 36–35 Millionen Jahre. Ohne sichere Schichtprovenienz gilt breiter ungefähr 37,7–34 Millionen Jahre.',
    'The latest stratigraphic review dates the main Baltic succinite horizon to the late Eocene, about 36–35 million years ago. Without secure layer provenance, a broader range of roughly 37.7–34 million years is appropriate.',
    ['Hvor gammel er baltisk rav mere præcist?','Wie alt ist baltischer Bernstein genauer?','How old is Baltic amber more precisely?']),
  fact('loose-piece-age-limit', /(?:bestemme|se).*(?:alder).*(?:ravstykke|rav)|alder.*udseende|alter.*(?:aussehen|stück bernstein)|age.*(?:appearance|piece of amber)|date.*amber.*look/iu,
    'direct-amber', ['ross-age-2026'],
    'Et løst strandfund kan ikke dateres præcist fra farve, form eller overflade. Forskere daterer normalt det geologiske lag omkring ravet; genaflejring kan have fjernet den nødvendige sammenhæng.',
    'Ein loser Strandfund lässt sich nicht anhand von Farbe, Form oder Oberfläche genau datieren. Forschende datieren gewöhnlich die umgebende Schicht; Umlagerung kann diesen Zusammenhang zerstört haben.',
    'A loose beach find cannot be dated precisely from colour, shape or surface. Researchers usually date the surrounding geological layer, and redeposition may have removed that context.',
    ['Kan jeg se alderen på et ravstykke?','Kann ich das Alter eines Bernsteinstücks am Aussehen erkennen?','Can I date a piece of amber from its appearance?']),
  fact('blue-earth-source', /blå jord.*rav|blue earth.*amber|blaue erde.*bernstein|upper blue earth|ober.*blaue erde/iu,
    'direct-amber', ['ross-age-2026'],
    'Den såkaldte Øvre Blå Jord i den preussiske formation ved Samland rummer den største kendte koncentration af baltisk succinit. Strandrav kan dog også være eroderet ud af yngre, genaflejrede lag.',
    'Die sogenannte Obere Blaue Erde der Preußischen Formation im Samland enthält die größte bekannte Konzentration baltischen Succinites. Strandbernstein kann aber auch aus jüngeren umgelagerten Schichten erodiert sein.',
    'The Upper Blue Earth of the Prussian Formation on Samland contains the largest known concentration of Baltic succinite. Beach amber may also have eroded from younger, redeposited layers.',
    ['Hvad er den blå jord med rav?','Was ist die Blaue Erde mit Bernstein?','What is the Blue Earth amber layer?']),
  fact('danish-glacial-transport', /istid.*(?:rav|flyttet)|gletsjer.*rav|eiszeit.*bernstein|gletscher.*bernstein|ice age.*amber|glacial.*amber.*denmark/iu,
    'official-guidance', ['geus-fanoe','rr-systematic-review'],
    'Noget rav i Danmark er blevet flyttet og genaflejret af is og smeltevand under istiderne og senere af havet. Et dansk strandfund behøver derfor ikke være kommet direkte fra sit oprindelige baltiske lag.',
    'Ein Teil des Bernsteins in Dänemark wurde während der Eiszeiten durch Eis und Schmelzwasser und später durch das Meer umgelagert. Ein Strandfund muss daher nicht direkt aus seiner ursprünglichen baltischen Schicht stammen.',
    'Some amber in Denmark was moved and redeposited by ice and meltwater during glacial periods and later by the sea. A Danish beach find need not have come directly from its original Baltic layer.',
    ['Har istiden flyttet rav til Danmark?','Hat die Eiszeit Bernstein nach Dänemark gebracht?','Did the Ice Age move amber to Denmark?']),
  fact('botanical-origin', /hvilket træ.*rav|ravtræ|træart.*(?:rav|harpiks)|welcher baum.*bernstein|bernsteinbaum|baumart.*bernstein|which tree.*amber|amber tree|tree species.*amber/iu,
    'direct-amber', ['wolfe-origin-2009','seyfullah-resin-2018'],
    'Baltisk rav stammer fra nåletræsharpiks, men den præcise producent er fortsat fagligt diskuteret. FTIR- og plantefossiler peger blandt andet mod en slægtning til paraplyfyrfamilien; det er en stærk hypotese, ikke endeligt facit.',
    'Baltischer Bernstein stammt aus Nadelbaumharz, doch der genaue Erzeuger bleibt umstritten. FTIR und Pflanzenfossilien weisen unter anderem auf Verwandte der Schirmtannenfamilie hin; das ist eine starke Hypothese, kein endgültiger Beweis.',
    'Baltic amber came from conifer resin, but the exact producer remains debated. FTIR and plant fossils point in part to relatives of the umbrella-pine family; this is a strong hypothesis, not a final answer.',
    ['Hvilket træ lavede baltisk rav?','Welcher Baum erzeugte baltischen Bernstein?','Which tree produced Baltic amber?']),
  fact('amber-forest', /ravskov.*(?:hvordan|én|ens)|amber forest.*(?:like|single)|bernsteinwald.*(?:wie|einheitlich)|skoven.*rav.*mangfold/iu,
    'direct-amber', ['seyfullah-resin-2018','wolfe-origin-2009'],
    '“Ravskoven” var næppe én ensartet skov. Plantefund peger på en mosaik af nåle- og løvtræer samt fugtige, kystnære og tørrere levesteder; ravet bevarer kun et selektivt udsnit.',
    'Der „Bernsteinwald“ war wohl kein einheitlicher Wald. Pflanzenfunde weisen auf ein Mosaik aus Nadel- und Laubbäumen sowie feuchten, küstennahen und trockeneren Lebensräumen hin; Bernstein bewahrt nur einen Ausschnitt.',
    'The “amber forest” was probably not one uniform forest. Plant evidence points to a mosaic of conifers, broad-leaved trees, wet coastal settings and drier habitats; amber preserves only a selective sample.',
    ['Hvordan så ravskoven ud?','Wie sah der Bernsteinwald aus?','What was the amber forest like?']),
  fact('inclusions-trapped', /hvordan.*(?:insekt|dyr|plante).*rav|indeslutning.*dannet|wie.*(?:insekt|tier|pflanze).*bernstein|einschluss.*entstand|how.*(?:insect|animal|plant).*amber|inclusion.*form/iu,
    'direct-amber', ['seyfullah-resin-2018','gia-amber'],
    'Små dyr, plantedele, pollen eller luft kan blive fanget i flydende harpiks. Harpiksen hærder omkring dem, men kun hvis både harpiks og indhold senere overlever begravelse og den lange modning til rav.',
    'Kleine Tiere, Pflanzenteile, Pollen oder Luft können in flüssigem Harz eingeschlossen werden. Das Harz härtet darum aus, doch beides muss Begrabung und lange Reifung zum Bernstein überstehen.',
    'Small animals, plant fragments, pollen or air may become trapped in flowing resin. The resin hardens around them, but both resin and contents must survive burial and long maturation into amber.',
    ['Hvordan bliver et insekt fanget i rav?','Wie wird ein Insekt im Bernstein eingeschlossen?','How does an insect become trapped in amber?']),
  fact('inclusion-bias', /(?:indeslutninger|insekter i rav).*(?:repræsentativ|alle|fortæller)|einschlüsse.*(?:repräsentativ|alle)|amber inclusions.*(?:represent|all|bias)/iu,
    'direct-amber', ['seyfullah-resin-2018'],
    'Indeslutninger er ikke en neutral optælling af fortidens liv. Harpiks fangede bestemte små organismer tæt på træet, mens mange andre aldrig kom i kontakt med den eller ikke blev bevaret.',
    'Einschlüsse sind keine neutrale Zählung des damaligen Lebens. Harz fing bestimmte kleine Organismen nahe am Baum; viele andere berührten es nie oder wurden nicht erhalten.',
    'Inclusions are not an unbiased census of past life. Resin trapped particular small organisms near the tree, while many others never contacted it or were not preserved.',
    ['Viser indeslutninger i rav alle dyr fra ravskoven?','Zeigen Einschlüsse alle Tiere des Bernsteinwaldes?','Do amber inclusions represent all animals in the amber forest?']),
  fact('amber-colour-range-research', /(?:hvilke|andre).*farver.*rav|rav.*(?<![\p{L}\p{N}_])(?:blå|grøn(?:t|ne)?|rød(?:t|e)?|hvid(?:t|e)?)(?![\p{L}\p{N}_])|welche.*farben.*bernstein|bernstein.*(?<![\p{L}\p{N}_])(?:blau|grün|rot|weiß)(?:e|er|es|en|em)?(?![\p{L}\p{N}_])|what colours.*amber|amber.*(?<![\p{L}\p{N}_])(?:blue|green|red|white)(?![\p{L}\p{N}_])/iu,
    'official-guidance', ['gia-amber','amber-spectroscopy-2025'],
    'Naturligt rav findes ikke kun i honninggul. Det kan være næsten farveløst, hvidligt, gult, orange, rødt, brunt og i sjældne tilfælde vise grønne eller blå optiske virkninger; farve alene beviser ikke ægthed.',
    'Natürlicher Bernstein ist nicht nur honiggelb. Er kann fast farblos, weißlich, gelb, orange, rot oder braun sein und selten grüne oder blaue optische Effekte zeigen; Farbe allein beweist keine Echtheit.',
    'Natural amber is not only honey-yellow. It can be nearly colourless, whitish, yellow, orange, red or brown and may rarely show green or blue optical effects; colour alone does not prove authenticity.',
    ['Hvilke andre farver kan rav have?','Welche anderen Farben kann Bernstein haben?','What other colours can amber have?']),
  fact('amber-opacity', /hvorfor.*rav.*(?:uklar|hvid|uigennemsigtig)|warum.*bernstein.*(?:trüb|weiß|undurchsichtig)|why.*amber.*(?:cloudy|white|opaque)/iu,
    'direct-analysis', ['gia-amber','gia-heat-treatment','amber-spectroscopy-2025'],
    'Uklarhed og hvidlige områder kan skyldes meget små bobler og lysspredning i materialet. Varmebehandling kan også ændre bobler, klarhed og farve, så udseendet alene afslører ikke hele historien.',
    'Trübung und weißliche Bereiche können durch sehr kleine Blasen und Lichtstreuung entstehen. Wärmebehandlung kann Blasen, Klarheit und Farbe ebenfalls verändern; das Aussehen erzählt daher nicht die ganze Geschichte.',
    'Cloudiness and whitish areas can result from tiny bubbles and light scattering. Heat treatment can also alter bubbles, clarity and colour, so appearance alone does not reveal the whole history.',
    ['Hvorfor er noget rav hvidt og uklart?','Warum ist mancher Bernstein weiß und trüb?','Why is some amber white and cloudy?']),
  fact('amber-hardness', /hvor hårdt.*rav|rav.*mohs|wie hart.*bernstein|bernstein.*mohs|how hard.*amber|amber.*mohs/iu,
    'official-guidance', ['gia-amber'],
    'Rav er blødt for en smykkesten, omkring 2–2,5 på Mohs-skalaen. Det kan derfor ridses og få trykmærker lettere end glas og mange mineraler, så opbevar det adskilt fra hårde genstande.',
    'Bernstein ist für einen Schmuckstein weich, etwa 2–2,5 auf der Mohs-Skala. Er wird leichter als Glas und viele Minerale zerkratzt oder eingedrückt und sollte getrennt von harten Gegenständen liegen.',
    'Amber is soft for a gem, about 2–2.5 on the Mohs scale. It scratches and dents more easily than glass and many minerals, so store it separately from hard objects.',
    ['Hvor hårdt er rav på Mohs-skalaen?','Wie hart ist Bernstein auf der Mohs-Skala?','How hard is amber on the Mohs scale?']),
  fact('amber-static', /^(?!.*(?:permittiv|permittivity|dielektr|dielectric))(?=.*(?:rav|bernstein|amber))(?=.*(?:statisk|elektrisk|tiltrækker|statisch|elektrisch|anzieh|static|electric|attract))/iu,
    'official-guidance', ['gia-amber'],
    'Rav kan blive statisk elektrisk, når det gnides, og derefter tiltrække meget lette fibre eller papirstumper. Effekten er historisk kendt, men andre plastmaterialer kan gøre det samme.',
    'Bernstein kann sich beim Reiben statisch aufladen und dann sehr leichte Fasern oder Papierschnipsel anziehen. Der Effekt ist historisch bekannt, kommt aber auch bei Kunststoffen vor.',
    'Amber can acquire a static electric charge when rubbed and then attract very light fibres or paper. The effect is historically well known, but plastics can do the same.',
    ['Kan rav blive statisk elektrisk?','Kann Bernstein statisch elektrisch werden?','Can amber become statically electric?']),
  fact('amber-density-number', /(?:massefylde|densitet).*(?:tal|g\/cm|rav)|(?:tal|g\/cm).*(?:ravets massefylde)|dichte.*(?:zahl|g\/cm|bernstein)|specific gravity.*amber|amber density.*number/iu,
    'direct-amber-experiment', ['lofty-transport-2023','gia-amber','rr-systematic-review'],
    'Baltisk rav angives ofte omkring 1,05–1,10 g/cm³, men stykker varierer. Et kontrolleret forsøg målte sine 5 mm ravkugler til cirka 1,041 g/cm³; ét forsøgs materiale er ikke en universel ravværdi.',
    'Baltischer Bernstein wird oft mit etwa 1,05–1,10 g/cm³ angegeben, doch Stücke variieren. Ein kontrollierter Versuch maß seine 5-mm-Bernsteinkugeln mit etwa 1,041 g/cm³; das ist kein universeller Wert.',
    'Baltic amber is often reported around 1.05–1.10 g/cm³, but pieces vary. One controlled experiment measured its 5 mm amber spheres at about 1.041 g/cm³; that sample is not a universal amber value.',
    ['Hvad er ravets massefylde i tal?','Welche Dichte hat Bernstein als Zahl?','What is amber density as a number?']),
  fact('amber-light-weight', /hvorfor.*rav.*(?:let|vejer lidt)|warum.*bernstein.*(?:leicht|wenig wiegt)|why.*amber.*(?:light|weigh so little)/iu,
    'official-guidance', ['gia-amber'],
    'Rav føles let, fordi dets massefylde kun ligger lidt over vandets og langt under glas og de fleste sten. Den lave vægt er et spor, men let plast kan efterligne den.',
    'Bernstein wirkt leicht, weil seine Dichte nur wenig über Wasser und weit unter Glas oder den meisten Steinen liegt. Das geringe Gewicht ist ein Hinweis, kann aber von leichtem Kunststoff nachgeahmt werden.',
    'Amber feels light because its density is only slightly above water and far below glass or most stones. Low weight is a clue, but light plastics can imitate it.',
    ['Hvorfor vejer rav så lidt?','Warum ist Bernstein so leicht?','Why does amber weigh so little?']),
  fact('weathered-crust', /rav.*(?:forvitr|skorpe|overflade).*strand|bernstein.*(?:verwitter|kruste|oberfläche)|amber.*(?:weathered|crust|surface skin)/iu,
    'direct-amber', ['ross-age-2026','amber-conservation-2021'],
    'Rav kan udvikle en mørkere eller mat forvitret overflade, mens et frisk brud ser anderledes ud. Skorpen fortæller om påvirkning og oxidation, men kan ikke alene datere eller bestemme oprindelsen.',
    'Bernstein kann eine dunklere oder matte verwitterte Oberfläche entwickeln, während ein frischer Bruch anders aussieht. Die Kruste zeigt Alterung und Oxidation, datiert oder bestimmt die Herkunft aber nicht allein.',
    'Amber can develop a darker or matt weathered surface while a fresh break looks different. The crust records exposure and oxidation but cannot by itself date the piece or establish its origin.',
    ['Hvad er den forvitrede skorpe på rav?','Was ist die verwitterte Kruste auf Bernstein?','What is the weathered crust on amber?']),
  fact('amber-heat-sensitive', /rav.*(?:varme|sol|radiator|temperatur).*skade|hitze.*bernstein.*schad|bernstein.*(?:sonne|heizung)|heat.*damage.*amber|amber.*(?:sun|radiator|high temperature)/iu,
    'direct-amber', ['amber-conservation-2021','gia-heat-treatment'],
    'Rav er varme- og lysfølsomt. Høj varme og langvarigt kraftigt lys kan ændre farve, klarhed, kemi og overflade og fremme revner; undgå solrige vindueskarme, radiatorer og varm behandling.',
    'Bernstein ist wärme- und lichtempfindlich. Hohe Wärme und langes starkes Licht können Farbe, Klarheit, Chemie und Oberfläche verändern und Risse fördern; meide sonnige Fensterbänke, Heizkörper und Erhitzen.',
    'Amber is sensitive to heat and light. High heat and prolonged strong light can alter colour, clarity, chemistry and surface and promote cracking; avoid sunny windowsills, radiators and hot treatment.',
    ['Kan varme og sol skade rav?','Können Hitze und Sonne Bernstein schädigen?','Can heat and sunlight damage amber?']),
  fact('copal-difference', /forskel.*(?:kopal|copal).*rav|kopal.*(?:rav|forskel)|unterschied.*kopal.*bernstein|kopal.*bernstein|difference.*copal.*amber|copal.*amber/iu,
    'direct-amber', ['seyfullah-resin-2018'],
    'Kopal bruges om yngre eller mindre fuldt modnet harpiks, men grænsen til rav er ikke defineret ens i alle fagtraditioner. En sikker skelnen kan kræve laboratorieanalyse frem for en enkel hjemmetest.',
    'Kopal bezeichnet jüngeres oder weniger vollständig gereiftes Harz, doch die Grenze zu Bernstein wird nicht überall gleich definiert. Eine sichere Trennung kann Laboranalyse statt eines einfachen Heimtests erfordern.',
    'Copal refers to younger or less fully matured resin, but the boundary with amber is not defined identically in every field. Reliable distinction may require laboratory analysis rather than a simple home test.',
    ['Hvad er forskellen på kopal og rav?','Was ist der Unterschied zwischen Kopal und Bernstein?','What is the difference between copal and amber?']),
  fact('amber-chemistry-lab', /(?=.*\b(?:rav(?:et|ets)?|bernsteins?|amber)\b)(?=.*(?:ftir|raman|spektroskop|spectroscop))|(?:kemisk|laboratorie).*bestemme.*rav|chemisch.*bernstein.*bestimm|laboratory.*identify.*amber/iu,
    'direct-analysis', ['amber-spectroscopy-2025','gia-root-amber'],
    'Laboratorier kan kombinere FTIR, Raman, mikroskopi, massefylde og andre analyser for at skelne naturmateriale, behandling og imitation. Raman kan vise kemiske forskelle og spor af ændringer, men naturlig variation og behandling kan give overlappende signaler. Sammenligning af overflade og indre samt andre analyser kan hjælpe. Et enkelt spektrum giver ikke en sikker præcis alder eller et entydigt forvitringsstadium.',
    'Labore können FTIR, Raman, Mikroskopie, Dichte und weitere Analysen kombinieren, um Naturmaterial, Behandlung und Imitation zu trennen. Raman kann chemische Unterschiede und Veränderungen zeigen, doch natürliche Variation und Behandlung können überlappende Signale liefern. Vergleiche zwischen Oberfläche und Innerem sowie andere Analysen können helfen. Ein einzelnes Spektrum ergibt kein sicheres genaues Alter oder eindeutiges Verwitterungsstadium.',
    'Laboratories can combine FTIR, Raman, microscopy, density and other analyses to distinguish natural material, treatment and imitation. Raman can reveal chemical differences and signs of alteration, but natural variation and treatment can produce overlapping signals. Comparing the surface and interior alongside other analyses can help. One spectrum does not establish a reliable exact age or an unambiguous weathering stage.',
    ['Hvordan bestemmer et laboratorium om noget er rav?','Wie bestimmt ein Labor, ob etwas Bernstein ist?','How does a laboratory identify amber?']),
  fact('fossil-resin-worldwide', /findes rav.*(?:andre steder|hele verden)|rav.*uden for baltikum|bernstein.*(?:weltweit|außerhalb.*baltikum)|amber.*(?:worldwide|outside.*baltic)/iu,
    'direct-amber', ['seyfullah-resin-2018','gia-amber'],
    'Fossilt rav findes mange steder i verden og i meget forskellige aldre og kemiske typer. “Baltisk rav” er derfor én vigtig ravgruppe, ikke et navn for alt naturligt rav.',
    'Fossile Harze kommen weltweit in unterschiedlichen Altern und chemischen Typen vor. „Baltischer Bernstein“ ist daher eine wichtige Gruppe und nicht die Bezeichnung für jeden natürlichen Bernstein.',
    'Fossil amber occurs worldwide in different ages and chemical types. “Baltic amber” is therefore one important amber group, not a name for all natural amber.',
    ['Findes der rav uden for Baltikum?','Gibt es Bernstein außerhalb des Baltikums?','Is amber found outside the Baltic region?']),
  fact('ancient-ecosystem', /hvad.*rav.*fortælle.*fortid|rav.*(?:økosystem|klima).*fortid|was.*bernstein.*vergangenheit|bernstein.*(?:ökosystem|klima)|what.*amber.*tell.*past|amber.*ancient ecosystem/iu,
    'direct-amber', ['seyfullah-resin-2018','gia-amber'],
    'Rav kan bevare små organismer, plantedele og kemiske spor fra gamle terrestriske miljøer. Fundene er værdifulde tidskapsler, men selektiv fangst og usikker lagproveniens begrænser, hvad ét stykke kan bevise.',
    'Bernstein kann kleine Organismen, Pflanzenteile und chemische Spuren alter Landökosysteme bewahren. Er ist eine wertvolle Zeitkapsel, doch selektiver Einschluss und unsichere Schichtprovenienz begrenzen die Aussage eines Stücks.',
    'Amber can preserve small organisms, plant fragments and chemical traces of ancient terrestrial environments. It is a valuable time capsule, but selective trapping and uncertain layer provenance limit what one piece can prove.',
    ['Hvad kan rav fortælle om fortidens økosystem?','Was kann Bernstein über frühere Ökosysteme erzählen?','What can amber tell us about ancient ecosystems?']),

  fact('raw-amber-look', /hvordan.*råt rav.*ud|råt rav.*kendetegn|wie sieht.*rohbernstein|rohbernstein.*aus|what does raw amber look like|raw amber appearance/iu,
    'official-guidance', ['gia-amber','rr-learning-design'],
    'Råt strandrav kan være mat, skorpet, uregelmæssigt og langt mindre gennemsigtigt end poleret smykkerav. Farve og overflade varierer, så brug flere skånsomme tegn og ikke et enkelt foto som facit.',
    'Roher Strandbernstein kann matt, verkrustet, unregelmäßig und viel weniger durchsichtig als polierter Schmuck sein. Farbe und Oberfläche variieren; nutze mehrere schonende Hinweise statt eines Fotos als Beweis.',
    'Raw beach amber may be matt, crusted, irregular and much less transparent than polished jewellery amber. Colour and surface vary, so use several gentle clues rather than treating one photograph as proof.',
    ['Hvordan ser råt rav ud?','Wie sieht Rohbernstein aus?','What does raw amber look like?']),
  fact('polished-amber-look', /poleret rav.*(?:anderledes|ud)|bernstein.*poliert.*(?:anders|aus)|polished amber.*(?:different|look)/iu,
    'official-guidance', ['gia-amber','gia-heat-treatment'],
    'Polering fjerner den ru forvitringshud og kan gøre farve, klarhed og indre strukturer tydeligere. Det betyder ikke nødvendigvis behandling ud over slibning, men poleret udseende kan skjule, hvordan stykket så ud på stranden.',
    'Polieren entfernt die raue Verwitterungshaut und macht Farbe, Klarheit und innere Strukturen sichtbarer. Das bedeutet nicht zwingend weitere Behandlung, kann aber das ursprüngliche Strandbild verdecken.',
    'Polishing removes the rough weathered skin and can reveal colour, clarity and internal structures. It does not necessarily imply treatment beyond abrasion, but it can hide how the piece looked on the beach.',
    ['Hvorfor ser poleret rav anderledes ud?','Warum sieht polierter Bernstein anders aus?','Why does polished amber look different?']),
  fact('uv-fluorescence-varies', /rav.*fluoresc.*(?:forskelligt|varier)|fluorescens.*rav.*varier|bernstein.*fluoresz.*(?:unterschied|variier)|amber fluorescence.*(?:vary|different)/iu,
    'direct-analysis', ['amber-spectroscopy-2025'],
    'Naturligt baltisk rav kan fluorescere med forskellig styrke og nuance, og opvarmning eller overfladeforandring kan ændre responsen. Manglende eller anderledes glød er derfor ikke alene et sikkert ja eller nej.',
    'Natürlicher baltischer Bernstein kann unterschiedlich stark und farbig fluoreszieren; Erwärmung oder Oberflächenveränderung kann die Reaktion ändern. Eine abweichende oder fehlende Leuchtwirkung ist allein kein sicheres Ja oder Nein.',
    'Natural Baltic amber can fluoresce with different strength and hue, and heating or surface change can alter the response. A weak, absent or unusual glow is not by itself a definitive yes or no.',
    ['Fluorescerer alt rav ens?','Fluoresziert jeder Bernstein gleich?','Does all amber fluoresce the same way?']),
  fact('uv-provenance-limit', /uv.*(?:oprindelse|baltisk|proveniens)|fluorescens.*oprindelse|uv.*(?:herkunft|baltisch)|fluoreszenz.*herkunft|uv.*(?:origin|baltic)|fluorescence.*provenance/iu,
    'direct-analysis', ['amber-spectroscopy-2025','gia-root-amber'],
    'UV-fluorescens kan være et nyttigt spor, men kan ikke alene bevise, at et stykke er naturligt baltisk rav eller afsløre dets geologiske oprindelse. Plast, glas, behandlinger og andre ravtyper kan give overlappende reaktioner.',
    'UV-Fluoreszenz ist ein nützlicher Hinweis, beweist allein aber weder natürlichen baltischen Bernstein noch seine geologische Herkunft. Kunststoffe, Glas, Behandlungen und andere Bernsteine können ähnlich reagieren.',
    'UV fluorescence is a useful clue but cannot by itself prove natural Baltic amber or establish geological origin. Plastics, glass, treatments and other ambers can produce overlapping responses.',
    ['Kan UV bevise at rav er baltisk?','Kann UV beweisen, dass Bernstein baltisch ist?','Can UV prove that amber is Baltic?']),
  fact('ftir-identification', /hvad.*ftir.*rav|ftir.*(?:identific|bestem).*rav|was.*ftir.*bernstein|ftir.*bernstein.*bestimm|what.*ftir.*amber|ftir.*identify.*amber/iu,
    'direct-analysis', ['amber-spectroscopy-2025','gia-root-amber'],
    'FTIR måler, hvordan materialet absorberer infrarødt lys, og giver et kemisk fingeraftryk. Det bruges blandt andet til at skelne ravtyper og opdage imitation eller behandling, normalt sammen med andre observationer.',
    'FTIR misst die Absorption von Infrarotlicht und erzeugt einen chemischen Fingerabdruck. Es hilft, Bernsteintypen, Imitationen oder Behandlungen zu unterscheiden, meist zusammen mit weiteren Untersuchungen.',
    'FTIR measures how a material absorbs infrared light and produces a chemical fingerprint. It helps distinguish amber types, imitations or treatment, usually alongside other observations.',
    ['Hvad er FTIR til rav?','Was ist FTIR bei Bernstein?','What is FTIR used for with amber?']),
  fact('microscope-identification', /mikroskop.*(?:rav|indeslutning)|rav.*mikroskop|mikroskop.*bernstein|bernstein.*mikroskop|microscope.*amber|amber.*microscope/iu,
    'direct-analysis', ['gia-root-amber','gia-fake-inclusion'],
    'Mikroskopi kan afsløre overflader, flowstrukturer, revner, samlinger og indeslutninger, som ikke ses med det blotte øje. Men naturlige bobler og kunstige detaljer kan ligne hinanden, så ekspertvurdering kan stadig være nødvendig.',
    'Mikroskopie kann Oberflächen, Fließstrukturen, Risse, Fugen und Einschlüsse sichtbar machen. Natürliche Blasen und künstliche Details können sich jedoch ähneln, sodass Fachanalyse nötig bleiben kann.',
    'Microscopy can reveal surfaces, flow structures, fractures, joins and inclusions invisible to the naked eye. Natural bubbles and artificial details may still resemble one another, so expert analysis can remain necessary.',
    ['Hvad kan et mikroskop vise i rav?','Was kann ein Mikroskop in Bernstein zeigen?','What can a microscope show in amber?']),
  fact('multiple-identification-tests', /hvor mange.*test.*rav|kombinere.*test.*rav|mehrere.*tests.*bernstein|tests.*kombinieren.*bernstein|combine.*tests.*amber|how many.*amber tests/iu,
    'official-guidance', ['gia-amber','gia-root-amber','amber-spectroscopy-2025'],
    'Sikker identifikation bygger ofte på flere uafhængige tegn: vægt, overflade, UV, mikroskopi og eventuelt spektroskopi. Når et sjældent eller værdifuldt fund er i tvivl, er en fagperson bedre end flere aggressive hjemmetests.',
    'Sichere Bestimmung stützt sich oft auf mehrere unabhängige Merkmale: Gewicht, Oberfläche, UV, Mikroskopie und gegebenenfalls Spektroskopie. Bei seltenen oder wertvollen Funden ist Fachanalyse besser als aggressive Heimtests.',
    'Reliable identification often combines independent clues: weight, surface, UV, microscopy and, when needed, spectroscopy. For a rare or valuable find, professional assessment is better than multiple aggressive home tests.',
    ['Skal jeg kombinere flere test af rav?','Soll ich mehrere Bernsteintests kombinieren?','Should I combine several tests for amber?']),
  fact('avoid-hot-needle', /varm nål.*rav|nåletest.*rav|heiße nadel.*bernstein|nadeltest.*bernstein|hot needle.*amber|needle test.*amber/iu,
    'official-guidance', ['gia-amber','amber-conservation-2021'],
    'Undgå en varm nål eller afbrænding. Testen ødelægger overfladen, kan frigive ubehagelig røg og er unødvendig, når ikke-destruktive tegn eller en faglig analyse kan bruges.',
    'Vermeide heiße Nadel oder Verbrennen. Der Test zerstört die Oberfläche, kann unangenehme Dämpfe freisetzen und ist unnötig, wenn zerstörungsfreie Hinweise oder Fachanalyse verfügbar sind.',
    'Avoid hot-needle or burn tests. They damage the surface, can release unpleasant fumes and are unnecessary when non-destructive clues or professional analysis are available.',
    ['Må jeg teste rav med en varm nål?','Soll ich Bernstein mit einer heißen Nadel testen?','Should I test amber with a hot needle?']),
  fact('avoid-scratch-test', /ridsetest.*rav|ridse.*rav.*test|kratztest.*bernstein|bernstein.*kratzen.*test|scratch test.*amber|scratch amber.*test/iu,
    'official-guidance', ['gia-amber'],
    'En ridsetest kan skade rav, fordi materialet kun er cirka 2–2,5 på Mohs-skalaen. Brug den ikke på et muligt fund; vælg observationer, som ikke efterlader mærker.',
    'Ein Kratztest kann Bernstein beschädigen, weil er nur etwa 2–2,5 auf der Mohs-Skala erreicht. Verwende ihn nicht an einem möglichen Fund; wähle spurenlose Beobachtungen.',
    'A scratch test can damage amber because the material is only about 2–2.5 on the Mohs scale. Do not use it on a possible find; choose observations that leave no mark.',
    ['Er en ridsetest god til rav?','Ist ein Kratztest für Bernstein geeignet?','Is a scratch test suitable for amber?']),
  fact('static-test-limit', /statisk test.*rav|gnide.*rav.*test|reibungstest.*bernstein|statischer test.*bernstein|static test.*amber|rub.*amber.*test/iu,
    'official-guidance', ['gia-amber'],
    'Gnidning og statisk tiltrækning kan støtte en mistanke, men er ikke et bevis. Mange plasttyper bliver også statiske, og fugt eller en ru overflade kan gøre testen svag.',
    'Reibung und statische Anziehung können einen Verdacht stützen, sind aber kein Beweis. Viele Kunststoffe laden sich ebenfalls auf; Feuchtigkeit oder raue Oberflächen können den Test schwächen.',
    'Rubbing and static attraction can support a suspicion but are not proof. Many plastics also become charged, while moisture or a rough surface may weaken the effect.',
    ['Kan den statiske test bevise rav?','Kann ein statischer Test Bernstein beweisen?','Can the static test prove amber?']),
  fact('plastic-imitation', /plast.*(?:ligne|efterligne).*rav|rav.*plastik|kunststoff.*bernstein.*(?:imit|ähn)|bernstein.*kunststoff|plastic.*imitate.*amber|amber.*plastic/iu,
    'direct-analysis', ['gia-root-amber','gia-amber'],
    'Plast kan efterligne ravets farve, lave vægt og endda UV-reaktion. Ensartede støbespor eller kunstige mønstre kan vække mistanke, men sikker identifikation kræver flere tegn.',
    'Kunststoff kann Farbe, geringes Gewicht und sogar UV-Reaktion von Bernstein nachahmen. Gleichmäßige Gussmerkmale oder künstliche Muster können verdächtig sein, doch sichere Bestimmung braucht mehrere Merkmale.',
    'Plastic can imitate amber’s colour, low weight and even UV response. Uniform mould marks or artificial patterns may raise suspicion, but reliable identification requires several clues.',
    ['Kan plastik ligne rav?','Kann Kunststoff wie Bernstein aussehen?','Can plastic imitate amber?']),
  // Match the material, not glasovergang/Glasübergang/glassy/fiberglass.
  // English "glass transition" also has a whole glass token but describes
  // a thermal property, not a glass imitation; leave that question unknown.
  fact('glass-imitation', /^(?!.*(?<![\p{L}\p{N}_])glass[ -]transition(?![\p{L}\p{N}_])).*(?:(?<![\p{L}\p{N}_])glas(?:set)?(?![\p{L}\p{N}_]).*(?:ligne|efterligne).*rav|rav.*(?<![\p{L}\p{N}_])glas(?:set)?(?![\p{L}\p{N}_])|(?<![\p{L}\p{N}_])glas(?![\p{L}\p{N}_]).*bernstein.*(?:imit|ähn)|bernstein.*(?<![\p{L}\p{N}_])glas(?![\p{L}\p{N}_])|(?<![\p{L}\p{N}_])glass(?![\p{L}\p{N}_]).*imitate.*amber|amber.*(?<![\p{L}\p{N}_])glass(?![\p{L}\p{N}_]))/iu,
    'direct-analysis', ['gia-amber'],
    'Glas kan ligne gennemsigtigt rav, men er normalt langt tungere og hårdere. Bobler kan findes i både glas og rav, så selv dette tegn bør ikke stå alene.',
    'Glas kann durchsichtigem Bernstein ähneln, ist aber gewöhnlich deutlich schwerer und härter. Blasen kommen sowohl in Glas als auch in Bernstein vor und sind allein kein Beweis.',
    'Glass can resemble transparent amber but is normally much heavier and harder. Bubbles may occur in both glass and amber, so even that clue should not be used alone.',
    ['Kan glas ligne rav?','Kann Glas wie Bernstein aussehen?','Can glass imitate amber?']),
  fact('pressed-amber', /presset rav|rekonstrueret rav|pressbernstein|rekonstruierter bernstein|pressed amber|reconstructed amber/iu,
    'direct-analysis', ['gia-root-amber'],
    'Presset eller rekonstrueret rav fremstilles ved at samle små ravstykker eller pulver under varme og tryk. Det kan stadig indeholde ægte ravmateriale, men er ikke ét uforandret naturligt stykke.',
    'Pressbernstein oder rekonstruierter Bernstein entsteht aus kleinen Stücken oder Pulver unter Wärme und Druck. Er kann echtes Bernsteinmaterial enthalten, ist aber kein einzelnes unverändertes Naturstück.',
    'Pressed or reconstructed amber is made by joining small amber fragments or powder under heat and pressure. It may contain genuine amber material but is not one unchanged natural piece.',
    ['Hvad er presset rav?','Was ist Pressbernstein?','What is pressed amber?']),
  fact('heat-treated-amber', /varmebehandlet rav|opvarmet rav.*behandling|hitzebehandelter bernstein|erhitzter bernstein|heat-treated amber|heated amber treatment/iu,
    'direct-experiment', ['gia-heat-treatment','amber-spectroscopy-2025'],
    'Varmebehandling kan gøre rav klarere, mørkere eller mere rødt og kan danne bestemte indre mønstre. Det behandlede materiale kan være ægte rav, men dets udseende er menneskeligt ændret.',
    'Wärmebehandlung kann Bernstein klarer, dunkler oder röter machen und bestimmte innere Muster erzeugen. Das Material kann echter Bernstein sein, sein Aussehen wurde jedoch vom Menschen verändert.',
    'Heat treatment can make amber clearer, darker or redder and can create particular internal patterns. The material may be genuine amber, but its appearance has been altered by people.',
    ['Hvad er varmebehandlet rav?','Was ist hitzebehandelter Bernstein?','What is heat-treated amber?']),
  fact('dyed-coated-amber', /farvet rav.*behandling|belagt rav|gefärbter bernstein|beschichteter bernstein|dyed amber|coated amber/iu,
    'direct-analysis', ['amber-spectroscopy-2025','gia-amber'],
    'Rav kan farves eller belægges for at ændre farve og overfladevirkning. Sådanne ændringer kan være svære at se uden forstørrelse eller spektroskopi og bør oplyses ved handel.',
    'Bernstein kann gefärbt oder beschichtet werden, um Farbe und Oberflächeneffekt zu ändern. Solche Eingriffe sind ohne Vergrößerung oder Spektroskopie schwer erkennbar und sollten beim Verkauf angegeben werden.',
    'Amber may be dyed or coated to change its colour and surface effect. Such alterations can be hard to see without magnification or spectroscopy and should be disclosed in trade.',
    ['Kan rav være farvet eller belagt?','Kann Bernstein gefärbt oder beschichtet sein?','Can amber be dyed or coated?']),
  fact('composite-amber', /sammensat rav|kompositrav|zusammengesetzter bernstein|kompositbernstein|composite amber|assembled amber/iu,
    'direct-analysis', ['gia-composite'],
    'Et kompositstykke kan bestå af flere dele, lim eller fyldmateriale, selv om noget af materialet er naturligt rav. Samlinger og fyld kan kræve mikroskopi eller laboratorieanalyse at opdage sikkert.',
    'Ein Kompositstück kann aus mehreren Teilen, Klebstoff oder Füllmaterial bestehen, obwohl ein Teil natürlicher Bernstein ist. Fugen und Füllungen erfordern oft Mikroskopie oder Laboranalyse.',
    'A composite piece may contain several parts, adhesive or filling even when some material is natural amber. Joins and fillers may require microscopy or laboratory analysis to detect reliably.',
    ['Hvad er kompositrav?','Was ist Kompositbernstein?','What is composite amber?']),
  fact('fake-inclusion', /falsk.*(?:insekt|indeslutning).*rav|kunstigt insekt.*rav|gefälschter.*(?:einschluss|insekt).*bernstein|fake.*(?:inclusion|insect).*amber/iu,
    'direct-analysis', ['gia-fake-inclusion'],
    'Insekter og andre indeslutninger kan forfalskes ved at skære, fylde eller samle materiale. En spektakulær indeslutning bør derfor vurderes af en specialist før rensning, slibning eller værdisætning.',
    'Insekten und andere Einschlüsse können durch Schneiden, Füllen oder Zusammensetzen gefälscht werden. Ein spektakulärer Einschluss sollte vor Reinigung, Schleifen oder Bewertung fachlich geprüft werden.',
    'Insects and other inclusions can be faked by cutting, filling or assembling material. A spectacular inclusion should therefore be assessed by a specialist before cleaning, polishing or valuation.',
    ['Kan et insekt i rav være falsk?','Kann ein Insekt im Bernstein gefälscht sein?','Can an insect in amber be fake?']),
  fact('unusual-inclusion', /fundet.*rav.*(?:insekt|plante|indeslutning)|rav med.*(?:insekt|plante).*hvad gør|bernstein.*(?:insekt|pflanze).*gefunden|found amber.*(?:insect|plant|inclusion)/iu,
    'official-guidance', ['gia-amber','amber-conservation-2021'],
    'Hvis et fund ser ud til at have en sjælden indeslutning, så undgå slibning, varme, olie og kemikalier. Fotografer det skånsomt, opbevar det stabilt og kontakt et naturhistorisk museum eller en kvalificeret ravspecialist.',
    'Bei einem Fund mit möglichem seltenem Einschluss: nicht schleifen, erhitzen, ölen oder chemisch behandeln. Schonend fotografieren, stabil lagern und ein Naturkundemuseum oder eine qualifizierte Fachperson kontaktieren.',
    'If a find appears to contain a rare inclusion, avoid polishing, heat, oil and chemicals. Photograph it gently, store it stably and contact a natural-history museum or qualified amber specialist.',
    ['Hvad gør jeg med rav med et insekt?','Was mache ich mit Bernstein mit einem Insekt?','What should I do with amber containing an insect?']),
  fact('clean-with-water', /rense rav.*vand|vaske rav.*vand|bernstein.*(?:wasser reinigen|abwaschen)|clean amber.*water|wash amber.*water/iu,
    'direct-amber', ['amber-conservation-2021'],
    'Et almindeligt strandfund kan normalt skylles forsigtigt i rent, lunkent vand og tørres med en blød klud. Stop, hvis stykket er sprækket, skørt eller har en mulig vigtig indeslutning.',
    'Ein gewöhnlicher Strandfund kann meist vorsichtig mit sauberem lauwarmem Wasser abgespült und mit einem weichen Tuch getrocknet werden. Bei Rissen, Sprödigkeit oder wichtigem Einschluss stoppen.',
    'An ordinary beach find can usually be rinsed gently in clean lukewarm water and dried with a soft cloth. Stop if it is cracked, fragile or may contain an important inclusion.',
    ['Må jeg rense rav med vand?','Darf ich Bernstein mit Wasser reinigen?','Can I clean amber with water?']),
  fact('avoid-solvents', /rav.*(?:alkohol|sprit|opløsningsmiddel)|alkohol.*rav|bernstein.*(?:alkohol|lösungsmittel)|amber.*(?:alcohol|solvent)/iu,
    'direct-amber', ['amber-conservation-2021'],
    'Undgå alkohol, acetone, desinfektionsmidler og andre opløsningsmidler på rav. De kan angribe eller udtørre overfladen, trænge ind i revner og skade både materialet og en mulig indeslutning.',
    'Vermeide Alkohol, Aceton, Desinfektionsmittel und andere Lösungsmittel auf Bernstein. Sie können die Oberfläche angreifen oder austrocknen, in Risse eindringen und Material sowie Einschlüsse schädigen.',
    'Avoid alcohol, acetone, disinfectants and other solvents on amber. They can attack or dry the surface, enter cracks and damage both the material and any inclusion.',
    ['Må jeg bruge alkohol til at rense rav?','Darf ich Bernstein mit Alkohol reinigen?','Can I use alcohol to clean amber?']),
  fact('avoid-oil', /olie.*rav.*(?:rense|behandle|blank)|rav.*olie|öl.*bernstein.*(?:reinigen|behandeln)|bernstein.*öl|oil.*amber.*(?:clean|treat|shine)/iu,
    'direct-amber', ['amber-conservation-2021'],
    'Olie kan midlertidigt gøre overfladen blank, men kan trænge ind i revner, samle snavs og skade eller skjule detaljer. Brug ikke olie på et muligt videnskabeligt eller værdifuldt fund.',
    'Öl kann die Oberfläche kurz glänzend machen, aber in Risse eindringen, Schmutz binden und Details schädigen oder verdecken. Verwende es nicht bei möglichen wissenschaftlich oder materiell wertvollen Funden.',
    'Oil can make the surface look glossy temporarily but may enter cracks, trap dirt and damage or hide detail. Do not oil a potentially scientific or valuable find.',
    ['Skal jeg smøre rav med olie?','Soll ich Bernstein mit Öl einreiben?','Should I oil amber?']),
  fact('dry-gently', /tørre rav.*(?:efter|rengøring)|rav.*lufttørre|bernstein.*trocknen|dry amber.*after cleaning/iu,
    'direct-amber', ['amber-conservation-2021'],
    'Dup ravet forsigtigt med en blød, ren klud og lad det tørre ved normal rumtemperatur. Undgå hårtørrer, radiator, direkte sol og kraftig gnidning.',
    'Tupfe Bernstein vorsichtig mit einem weichen sauberen Tuch ab und lasse ihn bei normaler Raumtemperatur trocknen. Vermeide Föhn, Heizkörper, direkte Sonne und starkes Reiben.',
    'Blot amber gently with a soft clean cloth and let it dry at normal room temperature. Avoid hair dryers, radiators, direct sun and vigorous rubbing.',
    ['Hvordan tørrer jeg rav efter rengøring?','Wie trockne ich Bernstein nach der Reinigung?','How should I dry amber after cleaning?']),
  fact('store-dark-stable', /opbevare rav.*(?:lys|mørkt|temperatur|fugt)|bernstein.*lagern.*(?:licht|dunkel|temperatur|feuchte)|store amber.*(?:light|dark|temperature|humidity)/iu,
    'direct-amber', ['amber-conservation-2021'],
    'Opbevar rav mørkt eller i svagt lys ved stabil, moderat temperatur og uden store fugtsvingninger. Museumspraksis viser, at lys, varme og ustabilt klima fremskynder overfladeændring og revnedannelse.',
    'Lagere Bernstein dunkel oder lichtarm bei stabiler mäßiger Temperatur und ohne große Feuchteschwankungen. Museumspraxis zeigt, dass Licht, Wärme und instabiles Klima Oberflächenalterung und Risse fördern.',
    'Store amber in darkness or low light at a stable, moderate temperature without large humidity swings. Museum practice shows that light, heat and unstable climate accelerate surface change and cracking.',
    ['Hvordan opbevarer jeg rav mørkt og stabilt?','Wie lagere ich Bernstein dunkel und stabil?','How should I store amber in stable conditions?']),
  fact('soft-separate-storage', /rav.*(?:pose|æske|separat).*opbevar|opbevare.*rav.*(?:blød|separat)|bernstein.*(?:beutel|schachtel|getrennt).*lagern|store amber.*(?:soft|separate|pouch)/iu,
    'official-guidance', ['gia-amber','amber-conservation-2021'],
    'Læg rav i en ren, blød og syrefri indpakning eller en lille æske, så det ikke gnider mod sten, metal eller andre hårde genstande. Undgå tæt plast med fanget fugt omkring et vådt fund.',
    'Lege Bernstein sauber, weich und säurefrei verpackt oder in eine kleine Schachtel, damit er nicht an Stein, Metall oder harten Gegenständen reibt. Nassen Fund nicht feucht in dichter Kunststoffverpackung einschließen.',
    'Place amber in clean, soft, acid-free wrapping or a small box so it cannot rub against stone, metal or other hard objects. Do not seal a wet find in tight plastic with trapped moisture.',
    ['Skal rav opbevares separat og blødt?','Soll Bernstein weich und getrennt gelagert werden?','Should amber be stored separately in something soft?']),

  fact('inventory-not-created', /(?:vejr|storm|bølger).*(?:skaber|laver).*rav|rav.*skabt.*storm|wetter.*(?:macht|erzeugt).*bernstein|storm.*erzeugt.*bernstein|weather.*(?:create|make).*amber|storm.*creates.*amber/iu,
    'mixed', ['rr-systematic-review','rr-user-spec'],
    'Vejr skaber ikke nyt rav. Bølger og strøm kan kun frigive og flytte rav, som allerede findes i et tilgængeligt lager; derfor kan to lignende storme give meget forskellige fund.',
    'Wetter erzeugt keinen neuen Bernstein. Wellen und Strömung können nur bereits vorhandenen, zugänglichen Bernstein lösen und bewegen; deshalb können ähnliche Stürme sehr unterschiedliche Funde bringen.',
    'Weather does not create new amber. Waves and current can only release and move amber already present in an accessible store, so two similar storms can produce very different finds.',
    ['Kan en storm skabe nyt rav?','Kann ein Sturm neuen Bernstein erzeugen?','Can a storm create new amber?']),
  fact('buried-availability', /rav.*(?:begravet|dækket).*sand|sand.*dækker.*rav|bernstein.*(?:vergraben|sand bedeckt)|sand.*bernstein.*bedeckt|amber.*(?:buried|covered).*sand/iu,
    'mixed', ['rr-systematic-review','guler-surf-2022'],
    'Rav kan være til stede, men utilgængeligt under sand eller i ældre lag. Erosion kan blotlægge det, mens ny aflejring kan skjule det igen; fysisk tilstedeværelse er derfor ikke det samme som fundbarhed.',
    'Bernstein kann vorhanden, aber unter Sand oder in älteren Schichten unzugänglich sein. Erosion kann ihn freilegen, neue Ablagerung wieder bedecken; Vorhandensein ist nicht gleich Auffindbarkeit.',
    'Amber can be present yet inaccessible beneath sand or in older layers. Erosion may expose it and new deposition may hide it again, so physical presence is not the same as findability.',
    ['Kan rav ligge begravet under sand?','Kann Bernstein unter Sand begraben liegen?','Can amber be buried under sand?']),
  fact('erosion-exposure', /erosion.*(?:rav|lager)|rav.*erosion|erosion.*bernstein|bernstein.*erosion|erosion.*amber|amber.*erosion/iu,
    'mixed', ['rr-systematic-review','ross-age-2026'],
    'Erosion kan skære ind i ravførende eller sekundære aflejringer og gøre gammelt materiale mobilt igen. Den samme erosion kan samtidig flytte rav væk, så erosion er en kildeproces og ikke en fundgaranti.',
    'Erosion kann bernsteinführende oder sekundäre Ablagerungen anschneiden und altes Material erneut mobilisieren. Dieselbe Erosion kann Bernstein auch wegführen; sie ist ein Quellprozess, keine Fundgarantie.',
    'Erosion can cut into amber-bearing or secondary deposits and remobilise old material. The same erosion may also carry amber away, so erosion is a source process rather than a find guarantee.',
    ['Hvordan kan erosion frigive rav?','Wie kann Erosion Bernstein freisetzen?','How can erosion release amber?']),
  fact('wave-fetch', /fetch.*(?:bølge|rav)|strækning.*vind.*vand.*bølger|windstreichlänge|fetch.*welle|fetch.*wave|wind distance.*wave/iu,
    'official-guidance', ['noaa-waves'],
    'Fetch er den ubrudte afstand, vinden blæser over vandet. Bølgestørrelse afhænger af vindstyrke, varighed og fetch sammen, så samme vindhastighed kan skabe meget forskellige bølger ved forskellige kyster.',
    'Fetch ist die ununterbrochene Strecke, über die Wind über Wasser weht. Wellengröße hängt gemeinsam von Windstärke, Dauer und Fetch ab; gleiche Windgeschwindigkeit kann daher sehr unterschiedliche Wellen erzeugen.',
    'Fetch is the uninterrupted distance over which wind blows across water. Wave size depends on wind strength, duration and fetch together, so the same wind speed can create very different waves at different coasts.',
    ['Hvad betyder fetch for bølger?','Was bedeutet Fetch für Wellen?','What does fetch mean for waves?'])
]);

function fact(id, pattern, evidenceClass, sourceIds, da, de, en, examples, extra = {}) {
  if (!validateRavAssistantSourceIds(sourceIds)) throw new Error(`Ukendt RavRadar-kilde i ${id}`);
  return Object.freeze({
    id,
    pattern,
    evidenceClass,
    sourceIds:Object.freeze([...sourceIds]),
    answers:Object.freeze({ da, de, en }),
    examples:Object.freeze([...examples]),
    volatile:Boolean(extra.volatile)
  });
}
